-- make_seed.py 로 만든 파일입니다. 여러 번 실행해도 안전합니다 (같은 id는 덮어씀).

on conflict (id) do update set category = excluded.category, dir1 = excluded.dir1, dir2 = excluded.dir2, title = excluded.title, subtitle = excluded.subtitle, author = excluded.author, subject = excluded.subject, content = excluded.content, toc = excluded.toc, abstract = excluded.abstract, publisher = excluded.publisher, pub_date = excluded.pub_date, kind = excluded.kind, form = excluded.form, language = excluded.language, scope = excluded.scope, source = excluded.source, contributor = excluded.contributor, refs = excluded.refs, base_date = excluded.base_date;
notify pgrst, 'reload schema';
